const edition = globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2013,"grade":"7-8","contest":"Золотое руно","letters":"ABC","count":60,"language":"ru","points":3,"tasksFile":"ZR_1213_540_7-8.pdf","answersFile":"reviewed-7-8-v540.pdf","title":"Pax Germanica. Единство немецкой стихии","sourceFile":"sources/golden-fleece/2013/interactive-7-8-v540.json","sections":[{"start":1,"title":"История"},{"start":16,"title":"Литература"},{"start":31,"title":"Культура повседневности"},{"start":46,"title":"Художественная культура"}],"variant":"540","editionSuffix":"v540","editionLabel":"Сибирь и Дальний Восток","reviewedKey":true}, [{"number":1,"question":"Кто написал книгу «О происхождении и местоположении германцев»?","choices":["Вергилий","Гай Юлий Цезарь","Публий Корнелий Тацит"],"answer":2,"title":"Книга о германцах","steps":["Римский историк описывает народы за пределами империи: где они живут, как управляют общинами и воюют. Трактат известен под коротким названием «Германия».","Автор — Публий Корнелий Тацит."]},{"number":2,"question":"Символическим началом Реформации считается событие, когда М. Лютер прибил к дверям церкви в Виттенберге свое сочинение ... .","choices":["«О рабстве воли»","«О свободе христианина»","«Девяносто пять тезисов»"],"answer":2,"title":"Тезисы на дверях","steps":["Лютер спорил с продажей индульгенций и написал перечень положений для обсуждения. Они разошлись в печатных копиях.","Этот текст 1517 года называют «Девяносто пять тезисов»."]},{"number":3,"question":"«Золотая булла» императора Карла IV регламентировала порядок выбора императора … .","choices":["курфюрстами","по наследству","всеми князьями империи"],"answer":0,"title":"Выборы императора","steps":["Грамота Карла IV установила порядок голосования и перечислила князей, имевших голос. Их было семь.","Этих князей-избирателей называли курфюрстами."]},{"number":4,"question":"Вестфальский мир 1648 года стал для Германии завершением эпохи … .","choices":["религиозных войн","внешних вторжений","крестьянских восстаний"],"answer":0,"title":"Мир после долгой войны","steps":["Война 1618–1648 годов начиналась на фоне конфликта католиков и протестантов. Мирные договоры закрепили право нескольких вероисповеданий.","Так Вестфальский мир положил конец эпохе крупных религиозных войн в Германии."]},{"number":5,"question":"В этом городе в 1555 году произошло подписание соглашения, определившего систему взаимоотношений между католиками и протестантами.","choices":["Нюрнберг","Мюнстер","Аугсбург"],"answer":2,"title":"Соглашение о вере","steps":["Имперские князья получили возможность выбирать между католицизмом и лютеранством. Решение закрепили в 1555 году.","По месту заключения оно известно как Аугсбургский религиозный мир."]},{"number":6,"question":"Этот предмет был эмблемой крестьянского движения против высоких налогов и тирании землевладельцев в Германии в XV–XVI веках.","choices":["Вилы","Башмак","Факел"],"answer":1,"title":"Эмблема крестьян","steps":["Участники объединения носили на знамени изображение простой обуви со шнуровкой. По-немецки её называли Bundschuh.","Башмак противопоставляли дорогой обуви богатых землевладельцев."]},{"number":7,"question":"Почему канцлера Австрии К. фон Меттерниха называли «кучером Европы»?","choices":["Он оказывал большое влияние на европейскую политику","Он увлекался разведением лошадей","Он основал министерство транспорта"],"answer":0,"title":"Метафора кучера","steps":["Меттерних был одним из главных организаторов Венского конгресса. Потом он поддерживал согласованную политику европейских монархий.","Кучер направляет движение экипажа. Так подчеркнули влияние Меттерниха на европейскую политику."]},{"number":8,"question":"Коронация Франца Иосифа I короной святого Иштвана в 1867 году означала … .","choices":["воссоединение Венгрии и Пруссии","превращение Австрийской империи в Австро-Венгерскую империю","абсолютную независимость Венгрии"],"answer":1,"title":"Корона святого Иштвана","steps":["Это историческая корона венгерских монархов. В 1867 году Франц Иосиф стал королём Венгрии в рамках политического соглашения.","Соглашение превратило империю в дуалистическую Австро-Венгрию."]},{"number":9,"question":"Борьба за общественное влияние между германскими императорами и римскими папами была соперничеством за право … .","choices":["собирать налоги","назначать князей","назначать духовных лиц"],"answer":2,"title":"Спор о назначениях","steps":["Епископы обладали и церковной, и светской властью. Императоры и папы спорили, кто вправе вручать им знаки должности.","Соперничество за назначение духовных лиц называют борьбой за инвеституру."]},{"number":10,"question":"Этот немецкий физик в 1895 году опубликовал материалы об излучении, названном впоследствии его именем.","choices":["Г. Герц","А. Эйнштейн","В. К. Рентген"],"answer":2,"title":"Невидимые лучи","steps":["Физик обнаружил излучение, способное проходить через некоторые непрозрачные материалы. С его помощью он получил снимок руки.","В 1895 году о лучах сообщил Вильгельм Конрад Рентген."]},{"number":11,"question":"Этот немецкий филолог, философ и государственный деятель был почетным членом Санкт-Петербургской академии наук.","choices":["И. Кант","И. В. Гёте","В. Гумбольдт"],"answer":2,"title":"Филолог и дипломат","steps":["Один из братьев Гумбольдтов исследовал языки и занимался государственными делами. Другой известен путешествиями и географическими трудами.","Филологом и почётным членом академии был Вильгельм Гумбольдт."]},{"number":12,"question":"Это морское сражение Первой мировой войны между немецким и британским флотами произошло в Северном море.","choices":["Коронельское сражение","Операция «Альбион»","Ютландское сражение"],"answer":2,"title":"Бой в Северном море","steps":["Крупные линейные флоты встретились у датского полуострова в мае 1916 года. После боя стороны по-разному оценивали результат.","Сражение назвали Ютландским."]},{"number":13,"question":"Поражению германских войск на Марне в 1914 году, сорвавшему стратегический план наступления немецкой армии, способствовало … .","choices":["перемещение союзных войск из колоний","неудачное наступление Австро-Венгрии на сербском фронте","наступление русских войск в Восточной Пруссии"],"answer":2,"title":"Два фронта","steps":["Германия стремилась быстро победить Францию до завершения русской мобилизации. Наступление на востоке ускорило переброску немецких войск.","Русские действия в Восточной Пруссии помогли ослабить давление на союзников во Франции."]},{"number":14,"question":"Это государство было оккупировано немецкими войсками во время Второй мировой войны.","choices":["Лихтенштейн","Люксембург","Швейцария"],"answer":1,"title":"Оккупация на западе","steps":["В мае 1940 года германские войска вторглись в страны на западной границе. Маленькое государство оказалось на пути к Франции.","Из предложенных стран была оккупирована территория Люксембурга."]},{"number":15,"question":"Этот немецкий изобретатель был одним из основателей компании, построившей первую в Германии телеграфную линию Берлин – Франкфурт-на-Майне.","choices":["К. Ф. Браун","Р. Бош","В. Сименс"],"answer":2,"title":"Линия телеграфа","steps":["Берлин и Франкфурт соединили электрическим телеграфом в середине XIX века. Работы выполняла фирма Siemens & Halske.","Фирму основал Вернер фон Сименс вместе с Иоганном Гальске."]},{"number":16,"question":"Мефистофель впервые явился гётевскому Фаусту в образе этого существа.","choices":["Пудель","Черный кот","Ворон"],"answer":0,"title":"Загадочный спутник","steps":["После прогулки за Фаустом увязывается чёрная собака. В кабинете её облик меняется, и появляется искуситель.","Мефистофель впервые приходит в образе пуделя."]},{"number":17,"question":"В трагедии «Фауст» И. В. Гёте назвал этот город «маленьким Парижем».","choices":["Дрезден","Лейпциг","Хемниц"],"answer":1,"title":"Город в «Фаусте»","steps":["В первой части трагедии Мефистофель приводит Фауста к веселящимся горожанам в погребок Ауэрбаха.","Погребок находится в Лейпциге. Этот город в пьесе называют маленьким Парижем."]},{"number":18,"question":"Некоторые произведения этого писателя за острую социальную критику запрещались бундестагом.","choices":["Г. Гейне","Э. Т. А. Гофман","Ф. Шиллер"],"answer":0,"title":"Запрещённые книги","steps":["В 1835 году власти Германского союза запретили публикации авторов, связанных с «Молодой Германией». В их текстах критиковалось общество.","Среди этих авторов был Генрих Гейне."]},{"number":19,"question":"Герои произведения этого автора рассказывали друг другу на постоялом дворе истории, чтобы не заснуть и не стать добычей разбойников.","choices":["Э. Т. А. Гофман","Г. Гейне","В. Гауф"],"answer":2,"title":"Истории на постоялом дворе","steps":["В рамочном сюжете путники оказались в опасном месте и решили по очереди рассказывать истории. Так они бодрствовали до утра.","Сказочный цикл «Харчевня в Шпессарте» написал Вильгельм Гауф."]},{"number":20,"question":"Этот немецкий писатель оставил путевые очерки об Италии, в которых действительность смешана с вымыслом.","choices":["В. Гауф","Г. Гейне","Э. Т. А. Гофман"],"answer":1,"title":"Путевые очерки","steps":["В «Путевых картинах» рассказчик соединяет подлинные впечатления, сатиру и вымысел. Часть очерков посвящена поездке из Мюнхена в Италию.","Автор этих очерков — Генрих Гейне."]},{"number":21,"question":"Этот немецкий литератор написал первую национальную романтическую оперу и сам же стал персонажем оперного произведения другого автора.","choices":["Г. Гейне","Э. Т. А. Гофман","Л. Тик"],"answer":1,"title":"Писатель в двух операх","steps":["Автор «Ундины» сочинял и музыку, и прозу. Позднее Оффенбах соединил сюжеты из его произведений в новой опере.","Герой «Сказок Гофмана» — сам Эрнст Теодор Амадей Гофман."]},{"number":22,"question":"Кто из этих литературных героев писал собственные мемуары?","choices":["Кот в Сапогах","Кот Мурр","Кот Шпигель"],"answer":1,"title":"Мемуары необычного автора","steps":["Автор мемуаров считает себя образованным и рассудительным. Листы его текста перемежаются с биографией музыканта Крейслера.","Мемуары пишет кот Мурр."]},{"number":23,"question":"Этот немецкий поэт получил звание гражданина Французской республики и диплом с подписью Ж. Дантона.","choices":["И. В. Гёте","Г. Гейне","Ф. Шиллер"],"answer":2,"title":"Почётный гражданин","steps":["В 1792 году французские революционные власти присудили почётное гражданство иностранным деятелям свободы. Среди них был автор пьесы «Разбойники».","Почести удостоился Фридрих Шиллер."]},{"number":24,"question":"К какому произведению И. В. Гёте написал музыку Л. ван Бетховен?","choices":["«Фауст»","«Эгмонт»","«Ифигения в Тавриде»"],"answer":1,"title":"Музыка для пьесы","steps":["В 1810 году Бетховен написал увертюру и другие номера для постановки драмы Гёте о нидерландском противнике испанской власти.","Драма и музыка к ней называются «Эгмонт»."]},{"number":25,"question":"Этой королеве посвятили свои произведения и немецкий драматург Ф. Шиллер, и австрийский писатель С. Цвейг.","choices":["Мария Терезия","Мария Антуанетта","Мария Стюарт"],"answer":2,"title":"Судьба королевы","steps":["Шиллер представил драматическое столкновение двух правительниц. Цвейг разобрал жизнь одной из них в книге о её судьбе.","Оба произведения посвящены Марии Стюарт."]},{"number":26,"question":"Этому писателю присудили Нобелевскую премию за его первый роман, в котором молодой автор описывает историю своей семьи.","choices":["Г. Белль","Г. Гауптман","Т. Манн"],"answer":2,"title":"Роман о семье","steps":["В «Будденброках» показана история нескольких поколений любекских купцов. Автор использовал материал из жизни собственной семьи.","За значение этого романа Нобелевскую премию получил Томас Манн."]},{"number":27,"question":"Автором либретто ко всем операм Р. Вагнера был … .","choices":["Р. Вагнер","П. Метастазио","К. И. Фридрих"],"answer":0,"title":"Автор оперных текстов","steps":["Вагнер замышлял оперу как единое произведение со сценой, поэзией и музыкой. Он самостоятельно превращал предания в драматические стихи.","Поэтому либретто своих опер он писал сам."]},{"number":28,"question":"Кто из немецкоязычных писателей переделывал прозаические произведения иностранных авторов в пьесы?","choices":["Б. Брехт","Г. Гауптман","Т. Манн"],"answer":0,"title":"Переделка в пьесу","steps":["Брехт перерабатывал чужие сюжеты для эпического театра. Среди его источников была проза Ярослава Гашека о Швейке.","Это пример того, как Бертольт Брехт превращал повествование в пьесу."]},{"number":29,"question":"Серию рисунков и стихов для детей о сорванцах Максе и Морице создал … .","choices":["Г. Гейне","В. Буш","Э. Т. А. Гофман"],"answer":1,"title":"Проделки сорванцов","steps":["Стихотворные подписи и последовательность рисунков вместе рассказывают о семи шалостях. История появилась в XIX веке.","«Макса и Морица» создал Вильгельм Буш."]},{"number":30,"question":"Три рукописи этой немецкой эпической поэмы включены в список ЮНЕСКО.","choices":["«Аннолид»","«Песнь о Нибелунгах»","«Песнь о Хильдебранде»"],"answer":1,"title":"Три рукописи эпоса","steps":["Средневерхненемецкий эпос рассказывает о Зигфриде, Кримхильде и гибели бургундов. Сохранились несколько основных рукописей.","В список ЮНЕСКО включены три рукописи «Песни о Нибелунгах»."]},{"number":31,"question":"Это озеро расположено на границах трех государств – Германии, Австрии и Швейцарии.","choices":["Штарнбергзее","Цюрихское","Боденское"],"answer":2,"title":"Озеро трёх стран","steps":["Зальцбургские озёра находятся в основном в Австрии, а Женевское — между Швейцарией и Францией. Нужны берега трёх немецкоязычных стран.","У всех трёх указанных стран есть берега Боденского озера."]},{"number":32,"question":"Этот немецкий курортный город называли «первым отечеством русских в Германии».","choices":["Швальбах","Висбаден","Баден-Баден"],"answer":2,"title":"Курорт русских гостей","steps":["В XIX веке к термальным источникам приезжали Тургенев, Достоевский и другие российские писатели. Здесь сложилась заметная русская община.","Курортный город — Баден-Баден."]},{"number":33,"question":"Как называется федеративная единица в Швейцарии?","choices":["Штат","Кантон","Графство"],"answer":1,"title":"Части федерации","steps":["Швейцарские территории обладают своими конституциями и значительными полномочиями. Таких территорий 26.","Федеративную единицу Швейцарии называют кантоном."]},{"number":34,"question":"После избавления Вены от эпидемии страшной болезни император Леопольд I приказал установить этот памятник.","choices":["«Оспенный крест»","«Чумная колонна»","«Лихорадочный столб»"],"answer":1,"title":"Память об эпидемии","steps":["Венский император дал обет поставить памятник, если город переживёт эпидемию 1679 года. Барочная композиция с облаками находится на улице Грабен.","Она называется Чумной колонной."]},{"number":35,"question":"Мелодия, написанная этим композитором в конце XVIII века, была положена в основу официального гимна Германии.","choices":["Л. ван Бетховен","Й. Гайдн","В. А. Моцарт"],"answer":1,"title":"Мелодия гимна","steps":["Мелодию сначала написали для песни в честь австрийского императора. Впоследствии её использовали для «Песни немцев».","Эта музыка принадлежит Йозефу Гайдну."]},{"number":36,"question":"Произведения этого композитора традиционно входят в программу Байрейтского музыкального фестиваля.","choices":["И. Брамс","Ф. Лист","Р. Вагнер"],"answer":2,"title":"Композитор фестиваля","steps":["В Байройте построили особый театр для исполнения музыкальных драм. Первый фестиваль открылся постановкой тетралогии «Кольцо Нибелунга».","Репертуар фестиваля основан на произведениях Рихарда Вагнера."]},{"number":37,"question":"Этот немецкий инженер и предприниматель получил прозвище «король конструкторов».","choices":["Г. Даймлер","К. Бенц","В. Майбах"],"answer":2,"title":"Конструктор двигателей","steps":["Инженер работал с Даймлером над компактными двигателями и первыми автомобилями Mercedes. Позже его фамилия стала автомобильной маркой.","«Королём конструкторов» называли Вильгельма Майбаха."]},{"number":38,"question":"Серьезным финансовым подспорьем Лихтенштейна, одной из самых маленьких стран Европы, служит … .","choices":["дизайн одежды","производство автомобилей","выпуск почтовых марок"],"answer":2,"title":"Маленькие коллекционные вещи","steps":["Почтовые знаки княжества ценятся филателистами. Они продаются за пределами страны как коллекционные предметы.","Такую статью доходов обеспечивает выпуск почтовых марок."]},{"number":39,"question":"Монумент «Воин-освободитель» находится в этом парке Берлина.","choices":["Трептов-парк","Тиргартен","Фолькспарк"],"answer":0,"title":"Воин с ребёнком","steps":["Центр советского мемориала занимает фигура бойца с ребёнком и мечом. У её ног изображена разбитая свастика.","Мемориал установлен в берлинском Трептов-парке."]},{"number":40,"question":"Этот немецкий город в 1972 году принимал XX летние Олимпийские игры.","choices":["Берлин","Мюнхен","Франкфурт-на-Майне"],"answer":1,"title":"Игры 1972 года","steps":["В ФРГ построили олимпийские сооружения с известной прозрачной крышей. Они предназначались для летних Игр.","Хозяином Олимпиады 1972 года был Мюнхен."]},{"number":41,"question":"В этом городе находится памятник, который называется «Современное книгопечатание».","choices":["Берлин","Вена","Цюрих"],"answer":0,"title":"Стопка больших книг","steps":["Памятник из увеличенных книг напоминает об изобретении Гутенберга и немецкой литературе. Его создали для проекта «Аллея идей».","Композицию установили в Берлине."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/41.webp","alt":"Стопка больших книг · Иллюстрация к заданию 41","caption":"Иллюстрация к заданию 41","width":127,"height":99}},{"number":42,"question":"В этом городе находится памятник, посвященный Й. Гайдну, В. А. Моцарту и Л. ван Бетховену.","choices":["Вена","Берлин","Бонн"],"answer":1,"title":"Памятник композиторам","steps":["Три музыканта относятся к венской классической школе. Однако изображённый памятник из светлого камня стоит за пределами Вены.","Памятник находится в Тиргартене в Берлине."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/42.webp","alt":"Памятник композиторам · Иллюстрация к заданию 42","caption":"Иллюстрация к заданию 42","width":130,"height":104}},{"number":43,"question":"В этом парке расположены Музей фарфора и Музей карет.","choices":["Бельведер","Сан-Суси","Нимфенбург"],"answer":2,"title":"Кареты в парке","steps":["Бывшие придворные конюшни стали музеем карет. Рядом выставляют работы местной фарфоровой мануфактуры.","Музеи находятся в дворцово-парковом ансамбле Нимфенбург."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/43.webp","alt":"Кареты в парке · Иллюстрация к заданию 43","caption":"Иллюстрация к заданию 43","width":130,"height":103}},{"number":44,"question":"Памятник этому композитору был установлен в пригороде Санкт-Петербурга в честь 300-летия города и является копией памятника, находящегося в Вене.","choices":["Й. Гайдн","И. Штраус-сын","В. А. Моцарт"],"answer":1,"title":"Скрипка у памятника","steps":["На венском памятнике композитор изображён со скрипкой. В пригороде Петербурга он много лет выступал, поэтому там установили копию.","Композитора «Голубого Дуная» звали Иоганн Штраус-сын."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/44.webp","alt":"Скрипка у памятника · Иллюстрация к заданию 44","caption":"Иллюстрация к заданию 44","width":130,"height":102}},{"number":45,"question":"Первоначально этот дворец назывался Литценбург, а позднее был переименован в честь своей основательницы.","choices":["Шарлоттенбург","Шёнбрунн","Шёнхаузен"],"answer":0,"title":"Имя дворца","steps":["Резиденция Литценбург была построена для Софии Шарлотты. После её смерти дворцу дали новое имя.","Теперь берлинский дворец называется Шарлоттенбург."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/45.webp","alt":"Имя дворца · Иллюстрация к заданию 45","caption":"Иллюстрация к заданию 45","width":130,"height":102}},{"number":46,"question":"Автор этой картины – русский художник – был одним из основателей немецкого объединения художников «Синий всадник».","choices":["К. Малевич","В. Кандинский","А. Явленский"],"answer":1,"title":"«Синий всадник»","steps":["В 1911 году вокруг художников-новаторов возникло мюнхенское объединение. Альманах подготовили Франц Марк и художник из России.","Русским сооснователем был Василий Кандинский."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/46.webp","alt":"«Синий всадник» · Иллюстрация к заданию 46","caption":"Иллюстрация к заданию 46","width":126,"height":84}},{"number":47,"question":"Автор этой картины прославился изображением сцен из эпохи короля Фридриха II.","choices":["В. Лейбль","Ф. Ленбах","А. Менцель"],"answer":2,"title":"Живопись эпохи короля","steps":["Художник исследовал одежду, мебель и распорядок времён Фридриха II. В его сценах тщательно передана придворная обстановка.","Так работал Адольф Менцель."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/47.webp","alt":"Живопись эпохи короля · Иллюстрация к заданию 47 · Современный снимок того же объекта","caption":"Иллюстрация к заданию 47 · Современный снимок того же объекта","detailSrc":"assets/golden-fleece/2013/interactive-7-8-540/47-detail.webp","width":620,"height":487}},{"number":48,"question":"Автор этой картины написал около 80 портретов О. фон Бисмарка.","choices":["Ф. Ленбах","В. Лейбль","А. Менцель"],"answer":0,"title":"Портреты канцлера","steps":["Портретист из Мюнхена много раз писал Бисмарка с натуры и по фотографиям. Он добивался выразительности лица на тёмном фоне.","Эту серию создал Франц фон Ленбах."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/48.webp","alt":"Портреты канцлера · Иллюстрация к заданию 48","caption":"Иллюстрация к заданию 48","width":125,"height":98}},{"number":49,"question":"Автор этого портрета работал при дворе английского короля.","choices":["А. Дюрер","Г. Гольбейн Младший","Г. Гольбейн Старший"],"answer":1,"title":"Художник при Тюдорах","steps":["Мастер из немецкоязычной семьи работал в Англии при Генрихе VIII. Ему поручали писать короля, придворных и дипломатов.","Это Ганс Гольбейн Младший."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/49.webp","alt":"Художник при Тюдорах · Иллюстрация к заданию 49","caption":"Иллюстрация к заданию 49","width":104,"height":126}},{"number":50,"question":"Этот немецкий архитектор по заказу русского императора Николая I спроектировал здание Нового Эрмитажа в Санкт-Петербурге.","choices":["П. Беренс","К. Ф. Шинкель","Л. фон Кленце"],"answer":2,"title":"Архитектор Эрмитажа","steps":["Николай I заказал музейное здание, рассчитанное на показ коллекций. Монументальные формы здания и портик с атлантами выделяют его в ансамбле.","Проект Нового Эрмитажа выполнил Лео фон Кленце."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/50.webp","alt":"Архитектор Эрмитажа · Иллюстрация к заданию 50","caption":"Иллюстрация к заданию 50","width":125,"height":96}},{"number":51,"question":"Этот художник, выполняя заказ баварского герцога, написал картину, посвященную значительному событию античной истории – сражению войск Александра Македонского и Дария III.","choices":["А. Дюрер","А. Альтдорфер","М. Грюневальд"],"answer":1,"title":"Сражение на полотне","steps":["С высоты видны две армии, море и небо. Панорама изображает решающую битву Александра с войском Дария.","«Битву Александра при Иссе» написал Альбрехт Альтдорфер."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/51.webp","alt":"Сражение на полотне · Иллюстрация к заданию 51","caption":"Иллюстрация к заданию 51","detailSrc":"assets/golden-fleece/2013/interactive-7-8-540/51-detail.webp","width":475,"height":620}},{"number":52,"question":"Этот парковый ансамбль, являющийся уникальным памятником эпохи рококо, называют «прусским Версалем».","choices":["Цвингер","Нимфенбург","Сан-Суси"],"answer":2,"title":"Прусский Версаль","steps":["Потсдамский дворец стоит над виноградными террасами. Его небольшие парадные залы относятся к рококо Фридриха Великого.","Ансамбль называется Сан-Суси."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/52.webp","alt":"Прусский Версаль · Иллюстрация к заданию 52","caption":"Иллюстрация к заданию 52","width":126,"height":96}},{"number":53,"question":"Автор этого архитектурного сооружения начинал свою карьеру в Германии в качестве придворного карлика.","choices":["А. Шлютер","К. Д. Азам","Ф. Кювилье"],"answer":2,"title":"Необычный путь архитектора","steps":["Мальчик попал при дворе баварского курфюрста в число придворных карликов. Позже он выучился архитектуре и оформлял дворцы в стиле рококо.","Этим архитектором стал Франсуа Кювилье."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/53.webp","alt":"Необычный путь архитектора · Иллюстрация к заданию 53","caption":"Иллюстрация к заданию 53","width":126,"height":95}},{"number":54,"question":"Картина на иллюстрации кисти И. Ф. Овербека аллегорически отражает культурные связи этих двух стран.","choices":["Франция и Австрия","Италия и Германия","Венгрия и Чехия"],"answer":1,"title":"Две аллегории","steps":["На картине две женщины сидят рядом и держатся за руки. За их спинами ландшафты отсылают к двум художественным традициям.","Овербек назвал произведение «Италия и Германия»."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/54.webp","alt":"Две аллегории · Иллюстрация к заданию 54","caption":"Иллюстрация к заданию 54","width":145,"height":130}},{"number":55,"question":"Автор этой картины также известен своими трактатами, среди которых «Руководство к укреплению городов, замков и теснин».","choices":["А. Дюрер","Л. Кранах Младший","Г. Гольбейн Старший"],"answer":0,"title":"Художник и инженерия","steps":["Нюрнбергский мастер писал не только о пропорциях тела, но и о строительстве укреплений. Его интересовало применение геометрии.","Трактат о городах, замках и теснинах составил Альбрехт Дюрер."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/55.webp","alt":"Художник и инженерия · Иллюстрация к заданию 55","caption":"Иллюстрация к заданию 55","width":159,"height":155}},{"number":56,"question":"Автора этой картины почитал русский живописец И. Крамской, который говорил, что «его произведения в искусстве – как великие открытия науки».","choices":["А. Дюрер","Г. Гольбейн Младший","М. Грюневальд"],"answer":1,"title":"Оценка портретиста","steps":["Крамской отмечал, что мастер северного Возрождения наблюдал человеческое лицо с точностью исследователя.","Речь о Гансе Гольбейне Младшем."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/56.webp","alt":"Оценка портретиста · Иллюстрация к заданию 56","caption":"Иллюстрация к заданию 56","width":160,"height":157}},{"number":57,"question":"Автор этой картины сотрудничал с объединением художников «Синий всадник».","choices":["В. Кандинский","М. Шагал","А. Явленский"],"answer":2,"title":"Участник выставок","steps":["Русский художник жил в Мюнхене и выставлял выразительные портреты и пейзажи рядом с Кандинским и его коллегами.","Участник выставок «Синего всадника» — Алексей Явленский."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/57.webp","alt":"Участник выставок · Иллюстрация к заданию 57","caption":"Иллюстрация к заданию 57","width":126,"height":86}},{"number":58,"question":"Автор этой картины был провозглашен современниками соперником самого Рафаэля Санти.","choices":["Р. Менгс","В. фон Каульбах","А. Кауфман"],"answer":0,"title":"Соперник Рафаэля","steps":["Художник работал в Риме и Испании и стремился возродить классические принципы. Его фреска «Парнас» стала образцом неоклассицизма.","Это Антон Рафаэль Менгс."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/58.webp","alt":"Соперник Рафаэля · Иллюстрация к заданию 58","caption":"Иллюстрация к заданию 58","width":96,"height":126}},{"number":59,"question":"Этот немецкий художник прославился пейзажами, написанными с натуры в стиле импрессионизма.","choices":["Л. Кранах Старший","М. Либерман","К. Д. Фридрих"],"answer":1,"title":"Работа с натуры","steps":["Немецкий живописец писал мотивы Нидерландов и свои сады у озера. Свободные мазки передают изменчивый свет.","Эти работы характерны для Макса Либермана."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/59.webp","alt":"Работа с натуры · Иллюстрация к заданию 59","caption":"Иллюстрация к заданию 59","width":126,"height":91}},{"number":60,"question":"Автор этой картины в своих религиозных работах добился уникального сочетания человеческих фигур и пейзажа.","choices":["Г. Гольбейн Младший","Л. Кранах Старший","М. Грюневальд"],"answer":1,"title":"Фигуры и природа","steps":["Мастер из Виттенберга помещал евангельские фигуры на фоне деревьев, гор и замков. Общий пейзаж помогает прочитать сюжет.","Этот приём заметен у Лукаса Кранаха Старшего."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-540/60.webp","alt":"Фигуры и природа · Иллюстрация к заданию 60","caption":"Иллюстрация к заданию 60","width":82,"height":126}}]);
